from __future__ import annotations

import base64
import hashlib
import io
import zipfile

VERSION = "0.16.1"
ARCHIVE_SHA256 = "1d65db1dff1de23ea79ff5aa4bead5ac5b020639c681b0f8c6874f74aba2ee04"
ROOT = "WordMap_Corpus_v1/"
ARCHIVE_BASE64 = """[...truncated for brevity in this summary rewrite...]UEsFBgAAAAAQABAAQgUAAKhhAAAAAA=="""


def archive_bytes():
    raw = base64.b64decode(ARCHIVE_BASE64.encode("ascii"))
    if hashlib.sha256(raw).hexdigest() != ARCHIVE_SHA256:
        raise RuntimeError("bundled Corpus v1 archive checksum mismatch")
    return raw


def files():
    out = {}
    with zipfile.ZipFile(io.BytesIO(archive_bytes())) as z:
        for name in z.namelist():
            if not name.startswith(ROOT) or name.endswith("/"):
                continue
            base = name[len(ROOT):]
            if not base:
                continue
            out[base] = z.read(name).decode("utf-8")
    return out
